p='Player.cpp'
s=open(p).read()
old=s[s.index('	// special preparations for launch in a rotating orbital'):s.index('}\n',s.index('SetVelocity(tangent + radial);'))+2]
new='''	if (!from) return;

	// special preparations for launch in a rotating orbital
	if (!from->IsGroundStation()) {
		SetFollowTarget(from);
		con->SetFollowMode(PlayerShipController::FOLLOW_ORI);
		SetAngVelocity(from->GetAngVelocity());
	}

	// some actions to avoid collision with the pad at start with a margin
	// (needed for both orbital and surface stations, otherwise the ship
	// is pressed into the pad on the first physics step and gets damaged)
	auto pPos = GetPosition();
	SetPosition(pPos + GetOrient().VectorY() * 0.01);
	auto tangent = from->GetAngVelocity().Cross(pPos);
	auto radial = GetOrient().VectorY() * 0.05;
	SetVelocity(tangent + radial);
'''
s=s.replace(old,new)
open(p,'w').write(s)
EOF
